    source_window_id:roster.source_window_id,source_revision:roster.source_revision,roster_sha256:roster.roster_sha256});
  const planById=new Map(planEntries.map(e=>{const body=sourceAt(work.payload.context.director_context,e.path);return [e.id,Object.freeze({...e,body})];}));
  const catalog=freezeProviderValue({schema_version:'mission-literal-catalog/2',work_id:work.work_id,
    payload_sha256:work.payload_sha256,master_session_id:work.master_session_id,
    source_window_id:roster.source_window_id,source_revision:roster.source_revision,
    roster_sha256:roster.roster_sha256,sources:catalogSources,plan_basis:planEntries.map(e=>[e.id,e.quote])});
  c1266LiteralCatalogs.set(work,{work_id:work.work_id,payload_sha256:work.payload_sha256,
    source_window_id:roster.source_window_id,source_revision:roster.source_revision,
    roster_sha256:roster.roster_sha256,byId,planById,catalog});
  return true;
}

